const PACKAGE={"id":"BFSdual_LF06_Lernpfad_LS6_2","ls":"6.2","title":"Lernpfadübung · LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","version":"1.0","source":"Fachbereiche/BFSdual/LF06/LS_6_2_Sortiment_auswaehlen.md"};
const COMP=[["Fachkompetenz","Ich wähle ein gemeinsames Kernsortiment für beide Läden. Ich wähle passende Ergänzungen für jeden Laden. Ich begründe jeden Artikel mit Nachfragebelegen. Ich achte darauf, wie viel Platz da ist und ob die Waren lieferbar sind."],["Personalkompetenz","Ich prüfe, ob meine Lieblingsartikel auch zur Nachfrage passen."],["Sozialkompetenz","Ich erkläre meine Gründe im Team. Ich einige mich mit den anderen auf eine Auswahl."],["Methodenkompetenz","Ich prüfe die Liste mit den Angaben zur Nachfrage, zum Platz und zur Lieferung."],["Medienkompetenz","Ich finde im Katalog Angaben zu den Artikeln. Ich halte die Auswahl übersichtlich fest."]];
const BANK=[{"c":0,"title":"Ein gemeinsames Angebot","scene":"Global Bike kündigt für die Aktion vier Artikel an, die bei Block in Aurich und in der Bike Arena Oltmanns in Leer angeboten werden. Die Läden erhalten zusätzlich Artikel für ihre eigene Kundschaft.","ask":"Welche Aussagen treffen zu?","answer":[1,4],"options":["Die Bike Arena entscheidet allein, welche Artikel auch Block führt.","Die vier Artikel, die beide Läden anbieten, bilden das Kernsortiment.","Die vier gemeinsamen Artikel werden insgesamt auf beide Läden verteilt.","Jede örtliche Ergänzung muss automatisch in beiden Läden stehen.","Eine lokale Ergänzung deckt einen Bedarf in einem bestimmten Laden ab.","Die Zahl der gemeinsamen Artikel hängt allein vom jeweils größten Laden ab."],"why":"Vier gemeinsame Artikel stehen jeweils in beiden Läden. Die örtlichen Ergänzungen sind für den Bedarf am jeweiligen Standort gedacht.","hint":"Achte darauf, was ‚gemeinsam‘ für jeden einzelnen Laden heißt.","steps":"Zeichne je Laden eine Spalte. Markiere, welche Felder sich in beiden Spalten entsprechen.","example":"Sieht die Kundschaft denselben Artikel im gemeinsamen Angebot, muss er bei beiden Partnern erhältlich sein.","sourceRefs":["Handlungssituation","M3","M6"],"id":0,"l":1,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":0,"title":"Lieferbar zum Start?","scene":"Sebastian hat die K70-Klingel auf seine Liste gesetzt. Bei Block gibt es vier, bei der Bike Arena fünf Nennungen. Christian meldet, dass die Klingel frühestens in der Folgewoche kommt.","ask":"Welche Konsequenz passt zur geplanten Aktionswoche?","answer":[2],"options":["Nimm die Klingel auf, weil beide Läden sie nachgefragt haben.","Setze die Klingel in Block ein. Für fünf Nennungen in Leer wäre sie erst später nötig.","Lass die Klingel für diese Aktion weg und prüfe lieferbare Artikel.","Plane die Klingel an beiden Standorten ein und lasse ihren Platz bis zur Lieferung frei.","Führe sie als lokalen Artikel in Leer, damit Block den Liefertermin nicht abwarten muss.","Behandle sie als Ersatzartikel, der sicher noch vor Aktionsbeginn geliefert wird."],"why":"Die Nachfrage ist belegt, aber die Klingel ist beim geplanten Start nicht lieferbar. Deshalb passt sie nicht in die Sortimentsliste für diese Aktion.","hint":"Schau auf den Zeitraum, den die Aktion tatsächlich abdeckt.","steps":"Stell zwei Fragen getrennt: Wird der Artikel nachgefragt? Steht er rechtzeitig bereit?","example":"Ein passender Artikel kann für eine spätere Aktion vorgemerkt werden, wenn er jetzt nicht rechtzeitig kommt.","sourceRefs":["Handlungssituation","M1","M2"],"id":1,"l":1,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":0,"title":"Eine mögliche Sortimentslücke","scene":"Bei Block wurde elfmal Schutz für nasse Sättel angesprochen. In einem ersten Entwurf der Aktionsliste fehlt ein Artikel für diesen Zweck.","ask":"Welche Aussagen helfen bei der Prüfung?","answer":[0,3,5],"options":["Der Wunsch kann auf eine Lücke im vorgeschlagenen Aktionssortiment hinweisen.","Elf Nennungen beweisen, dass Block allgemein keinen passenden Artikel führt.","Eine Lücke liegt vor, wenn ein Artikel im Katalog steht, aber noch niemand danach fragt.","Ein Sattelüberzug kann genau den festgehaltenen Wunsch aufgreifen.","Jede nicht ausgewählte Artikelgruppe ist automatisch eine Sortimentslücke.","Ob die Lücke im regulären Ladenangebot besteht, geht aus der Aktionsliste allein nicht hervor."],"why":"Eine Sortimentslücke verbindet einen belegten Wunsch mit einem fehlenden passenden Angebot. Der Entwurf sagt nur etwas über die Aktion, nicht über das gesamte gewöhnliche Sortiment.","hint":"Prüfe Bedarf und vorhandenes Angebot getrennt.","steps":"Vergleiche die Nachfrage mit der geplanten Auswahl. Gib an, auf welches Sortiment sich deine Aussage bezieht.","example":"Fehlt ein Pumpenmodell, kann trotzdem ein passender Pumpentyp angeboten werden. Dann fehlt nicht zwingend eine Lösung für den Bedarf.","sourceRefs":["M1","M2","M5","M6"],"id":2,"l":1,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":3,"title":"Nennungen verstehen","scene":"Eine Person fragt im Beratungsgespräch nach einem Licht und einem Schloss. Das Personal hält beide Wünsche fest.","ask":"Welche Aussagen treffen auf die Nachfrageübersicht in LS 6.2 zu?","answer":[1,2,5],"options":["Für jede Person darf in der Übersicht nur ein Wunsch erscheinen.","Ein Gespräch kann zwei Nennungen erzeugen.","Die Beratungstagebücher liefern Daten zu Fragen und Wünschen.","Aus zwei Nennungen folgen zwei abgeschlossene Käufe.","Die Zahl aller Nennungen entspricht automatisch der Zahl aller beratenen Personen.","Wenn du Nennungen vergleichst, beschreibe sie als Wünsche, nicht als Personen."],"why":"Die Übersicht zählt geäußerte Wünsche. In einem Gespräch kann mehr als ein Wunsch vorkommen. Die Zahlen sind weder Personen- noch Verkaufszahlen.","hint":"Was ist in dieser Übersicht die Zähleinheit?","steps":"Prüfe je Aussage, ob von Wünschen, Personen oder Käufen die Rede ist.","example":"Eine Person kann auf derselben Einkaufstour nach zwei verschiedenen Artikeln fragen, ohne einen zu kaufen.","sourceRefs":["M1","M6"],"id":3,"l":1,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":4,"title":"Artikel im Katalog finden","scene":"Im Katalog stehen T30 Rahmentasche, R40 Sattelüberzug, P50 Minipumpe und F60 Flaschenhalter. Die Kennung kommt ins Ergebnisblatt.","ask":"Welche Kombinationen sind korrekt?","answer":[0,4],"options":["P50 kennzeichnet die Minipumpe.","R40 kennzeichnet die Rahmentasche.","F60 kennzeichnet das LED-Lichtset.","Ein Katalogcode nennt die Zahl der Nennungen in beiden Läden.","T30 kennzeichnet die Rahmentasche.","Die Kennung ist überflüssig, wenn jeder Artikel einen Platz braucht."],"why":"Mit P50 und T30 sind die Minipumpe und die Rahmentasche eindeutig identifizierbar. Ein Code verrät keine Kundenzahl oder Platzbelegung.","hint":"Lies Name und Kennung in derselben Katalogzeile.","steps":"Vergleiche vollständige Kennungen, auch wenn mehrere Artikel ähnlich heißen.","example":"Wenn eine Ware eindeutig mit Artikelcode und Namen in der Liste steht, kann Jan sie leicht im Katalog wiederfinden.","sourceRefs":["M2","M5","M6"],"id":4,"l":1,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":4,"title":"Katalogzeile vollständig lesen","scene":"Eine Gruppe möchte die Minipumpe P50 einplanen. Laut Katalog ist sie zum Start lieferbar, belegt einen Platz und passt auf zwei gängige Ventilarten, die auf dem Artikel stehen.","ask":"Welche Angaben kannst du korrekt ins Ergebnisblatt übernehmen?","answer":[1,2,4],"options":["Die Pumpe passt auf jede Ventilart.","P50 belegt pro Laden einen Aktionsplatz.","P50 ist laut Katalog zum Start lieferbar.","P50 ist der Flaschenhalter.","Vor dem Kauf lassen sich die passenden Ventilarten am Artikel ablesen.","Die Zahl der nachgefragten Pumpen steht in der Spalte ‚Platzbedarf‘."],"why":"Der Katalog zeigt Kennung, Eignungsmerkmale, Lieferbarkeit und Platzbedarf. Zwei gängige Typen sind keine Zusage für jedes Ventil.","hint":"Trenne beschriebenes Merkmal, Lieferdatum und Platzbedarf.","steps":"Übernimm nur die Angaben, die in derselben Produktzeile stehen.","example":"Die Aussage ‚für zwei gängige Ventilarten‘ lässt sich nicht ohne weiteren Beleg zu ‚universell passend‘ erweitern.","sourceRefs":["M2","M5"],"id":5,"l":1,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":3,"title":"Plätze richtig zählen","scene":"Block hat fünf Aktionsplätze; die Bike Arena hat sechs. Jeder Artikel braucht genau einen Platz je Laden. Der siebte Stellplatz in Leer gehört zum eigenen Sortiment des Ladens.","ask":"Welche Platzplanung entspricht den Vorgaben?","answer":[0,3,5],"options":["Die vier gemeinsamen Artikel belegen je vier Plätze in Aurich und Leer.","Aus fünf und sechs Plätzen folgen elf unterschiedliche Aktionsartikel.","Die Bike Arena hat sieben Plätze für die Global-Bike-Aktion.","Bei Block bleibt nach dem Kernsortiment genau ein Platz für einen lokalen Artikel.","Die vier gemeinsamen Artikel belegen in den beiden Läden zusammen genau vier Plätze.","In Leer bleiben nach dem Kernsortiment zwei Aktionsplätze für lokale Artikel."],"why":"Ein gemeinsamer Artikel belegt einen Platz in jedem Laden. Damit bleiben bei Block 5 − 4 = 1 und bei der Bike Arena 6 − 4 = 2 Plätze für die Ergänzungen.","hint":"Rechne die Plätze für jeden Laden einzeln.","steps":"Zieh die vier gemeinsamen Plätze von fünf und von sechs ab. Der siebte Platz in Leer gehört nicht zur Aktion.","example":"Zwei Läden, die je drei gemeinsame Produkte zeigen, brauchen dafür sechs belegte Stellplätze.","sourceRefs":["M2","M3"],"id":6,"l":1,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":0,"title":"Warengruppen und Sortimentsbreite","scene":"Das Sortiment enthält ein Lichtset, zwei verschiedene Schlösser und eine Rahmentasche. Alle Produkte haben je eine eigene Artikelkennung.","ask":"Welche Aussagen treffen fachlich zu?","answer":[1,4],"options":["Die Sortimentsbreite beträgt vier Warengruppen, weil es vier Artikelcodes gibt.","Beleuchtung, Schlösser und Taschen bilden hier drei Warengruppen.","Ein zweites Schloss schafft automatisch eine neue Warengruppe.","Die Sortimentsbreite beschreibt, wie viele Exemplare der Händler liefern kann.","Ein zusätzliches Produkt derselben Warengruppe vergrößert nicht automatisch die Sortimentsbreite.","Vier belegte Aktionsplätze bedeuten immer vier verschiedene Warengruppen."],"why":"Die Sortimentsbreite zählt verschiedene Warengruppen. Zwei Schlossmodelle belegen zwei Artikelpositionen, gehören aber derselben Warengruppe an.","hint":"Sortiere nach Warenart statt nach Anzahl der Artikelnummern.","steps":"Ordne zuerst jeden Artikel einer Gruppe zu. Zähle dann nur die unterschiedlichen Gruppen.","example":"Zwei Lampen können zwei Plätze beanspruchen und trotzdem zur einen Warengruppe Beleuchtung gehören.","sourceRefs":["M3","M6"],"id":7,"l":1,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":1,"title":"Eigene Vorlieben überprüfen","scene":"Du würdest selbst das Multitool W90 kaufen. Im Beratungstagebuch stehen zum Nachziehen von Schrauben fünf Nennungen bei Block und acht in der Bike Arena.","ask":"Welche Überlegungen sind hilfreich?","answer":[0,3],"options":["Ich halte fest, dass meine Vorliebe eine erste Idee und noch kein Beleg ist.","Ich nehme W90 in beide Läden, weil ich das Werkzeug selbst gebrauchen kann.","Ich nehme W90 aus der Planung, weil eigene Vorlieben grundsätzlich nie passen.","Ich vergleiche die Nennungen für W90 mit den Belegen für andere Artikel je Laden.","Acht Nennungen beweisen, dass W90 in Leer häufiger verkauft wird als die Minipumpe.","Ich brauche die Platzprüfung nicht mehr, sobald ich einen Nachfragebeleg finde."],"why":"Die Nachfrage stützt W90 grundsätzlich. Ob es den begrenzten Platz bekommt, hängt vom Vergleich mit anderen Bedarfen und von seiner Rolle im Sortiment ab.","hint":"Wo endet deine eigene Erfahrung und wo beginnt der überprüfbare Fallbeleg?","steps":"Trenne persönliche Vorliebe, beobachteten Bedarf und spätere Auswahlentscheidung.","example":"Ein Produkt kann gut sein und trotzdem für einen knappen Aktionsplatz gegen ein anderes verlieren.","sourceRefs":["M1","M2","M3"],"id":8,"l":1,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":2,"title":"Sich im Team verständigen","scene":"Im Team möchte eine Person den Sattelüberzug R40 für Block. Eine zweite Person möchte dort den einen lokalen Platz für ein Reflektorband B80 nutzen.","ask":"Welche Beiträge helfen bei der Einigung?","answer":[1,3,4],"options":["Wir verteilen den einen Platz gleichzeitig an beide Artikel.","Ich frage beide nach dem Bedarf, den ihr Vorschlag erfüllt.","Ich setze zuerst meine Idee durch und suche danach einen Grund.","Wir prüfen die Nennungen zu Sattelschutz und zusätzlicher Sichtbarkeit in Aurich.","Wir entscheiden mit Belegen und halten den Grund für den Verzicht fest.","Die Zahl der Nennungen in Leer entscheidet allein über beide Vorschläge in Aurich."],"why":"Beide Vorschläge können sinnvoll sein. Die Nachfrage im betroffenen Laden und die verfügbare Fläche helfen, eine gemeinsame, nachvollziehbare Wahl zu treffen.","hint":"Klärt, worin sich der Nutzen der beiden Vorschläge unterscheidet.","steps":"Vergleicht beide Artikel anhand derselben Kriterien und erklärt den Grund für eure Entscheidung.","example":"Ein Artikel mit geringerem Bedarf kann trotzdem sinnvoll sein, wenn er eine wichtige Lücke schließt. Dafür braucht ihr eine konkrete Begründung.","sourceRefs":["M1","M2","M3","M5"],"id":9,"l":1,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":2,"title":"Mit beiden Läden sprechen","scene":"Block betont Zubehör für den Arbeitsweg. In Leer fragen Familien nach Zubehör fürs Trinken und für Pannen. Sebastian soll Entscheidungen beiden Partnern erklären können.","ask":"Welche Gesprächsbeiträge unterstützen den Vergleich?","answer":[0,2,5],"options":["Fasse je Laden einen konkreten Bedarf aus der Sortimentsrunde zusammen.","Frage nur den größeren Laden, weil er mehr Plätze hat.","Frage nach, ob ein gemeinsamer Artikel den Zweck an beiden Standorten erfüllen kann.","Versprich jedem Laden alle Artikel seiner Wunschliste.","Besprich nur Artikelcodes, damit die Gründe keine Rolle spielen.","Erkläre, warum ein örtlich besonders gut passender Artikel eine lokale Ergänzung sein kann."],"why":"Die Empfehlungen richten sich an beide Läden. Ein gemeinsamer Bedarf kann in den gemeinsamen Kern führen. Ein besonders lokaler Bedarf kann eine Ergänzung begründen.","hint":"Höre auf die unterschiedlichen Kaufanlässe.","steps":"Prüfe zuerst Gemeinsamkeiten und dann die Gründe für Unterschiede. Formuliere je Laden eine kurze Rückfrage.","example":"Zwei Geschäfte können beide Licht brauchen, aber bei Regenschutz oder Trinkpausen unterschiedliche Schwerpunkte setzen.","sourceRefs":["Handlungssituation","M1","M4"],"id":10,"l":1,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":1,"title":"Eine schwache Zahl richtig bewerten","scene":"In Leer wurde Schutz für nasse Sättel viermal angesprochen. Die Beobachtungen erwähnen zwei nasse Wochenenden.","ask":"Welche Schlussfolgerungen sind tragfähig?","answer":[2,4],"options":["Vier bedeutet, dass der Bedarf in Leer überhaupt nicht vorkommt.","Der Bedarf ist garantiert das ganze Jahr gleich hoch.","Das Wetter kann einen Teil der Beobachtung erklären.","Block muss den Sattelüberzug ebenfalls weglassen, weil die Zahl in Leer niedriger ist.","Prüfe die vier Nennungen zusammen mit den anderen Ursachen und Artikelwünschen.","Vier Nennungen zählen als exakt vier sicher verkaufte Sattelüberzüge."],"why":"Auch vier Nennungen sind ein Bedarfssignal. Die nassen Wochenenden helfen, es in den richtigen Zusammenhang zu stellen. Mehr als die vorliegenden Beobachtungen ist nicht belegt.","hint":"Eine niedrige Zahl ist kein Nullwert.","steps":"Schau neben die Tabelle: Welche Beobachtung zeigt, wann dieser Wunsch in Leer vorkam?","example":"Eine Regenwoche kann die Zahl der Fragen nach Regenschutz vorübergehend erhöhen.","sourceRefs":["M1"],"id":11,"l":1,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":0,"title":"Einen Kernartikel belegen","scene":"Für einen gemeinsamen Platz stehen L10 LED-Lichtset und R40 Sattelüberzug zur Diskussion. Für Licht bei Dunkelheit stehen 13 Nennungen bei Block und 8 in Leer. Für Sattelschutz sind es 11 und 4. Beide Artikel sind lieferbar.","ask":"Welche Folgerungen tragen die Angaben?","answer":[0,2,4],"options":["L10 lässt sich mit einem vergleichsweise starken Bedarf in beiden Läden begründen.","R40 ist automatisch der beste gemeinsame Artikel, weil elf mehr als acht sind.","Die Zahlen sprechen dafür, R40 besonders als Ergänzung bei Block zu prüfen.","Kein Artikel kann zum Kern gehören, wenn die Nennungszahlen in den Läden unterschiedlich sind.","Für L10 sollten im Ergebnisblatt die Belege beider Standorte stehen.","Wenn beide Artikel lieferbar sind, spielt die Nachfrage für den gemeinsamen Kern keine Rolle mehr."],"why":"Für einen Kernartikel zählen beide Standorte. L10 hat in beiden Läden einen deutlichen Beleg. Der Bedarf für R40 ist in Aurich stärker und kann eine örtliche Ergänzung begründen.","hint":"Vergleiche pro Artikel seine beiden Standortwerte.","steps":"Vergleiche erst Licht mit Sattelschutz je Laden. Prüfe danach, für welchen Bereich der jeweilige Artikel nachvollziehbar wäre.","example":"Zwei gute lokale Werte aus unterschiedlichen Zeilen können nicht zu einem Beleg für denselben Artikel zusammengezählt werden.","sourceRefs":["M1","M2","M3","M5"],"id":12,"l":2,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":0,"title":"Lokalen Artikel für Aurich auswählen","scene":"Für den letzten Platz bei Block sind R40 Sattelüberzug und F60 Flaschenhalter lieferbar. R40 hat 11 Nennungen in Aurich; F60 hat 4. Laut Beobachtung stehen Räder dort tagsüber häufig draußen.","ask":"Welche Empfehlung nutzt die stärkeren Belege für genau diesen Platz?","answer":[3],"options":["F60 für Aurich, weil 13 Nennungen aus Leer auch für Aurich zählen.","F60 und R40 für Aurich, weil beide im Lager verfügbar sind.","Keinen Artikel, da für die Aktion ausschließlich das Kernsortiment zugelassen ist.","R40 für Aurich, weil dort mehr Leute nach Sattelschutz fragen und viele Räder draußen stehen.","F60 für Aurich, weil der Katalog die Gewindeösen am Rahmen erwähnt.","R40 zusätzlich in beiden Läden, auch wenn dann der gemeinsame Kern größer als vier wäre."],"why":"R40 passt zum beschriebenen lokalen Bedarf und belegt genau den freien Platz. Die höhere Nachfrage für F60 in Leer ist kein Grund, ihn in Aurich vorzuziehen.","hint":"Welche Kundschaft nutzt den letzten Platz?","steps":"Vergleiche die zwei Werte in der Spalte ‚Block, Aurich‘ und prüfe die Fallbeobachtung zu Pendelnden.","example":"Eine lokale Ergänzung kann bei einem Laden gut passen, auch wenn die andere Kundschaft wenig danach fragt.","sourceRefs":["M1","M2","M3"],"id":13,"l":2,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":0,"title":"Zwei lokale Plätze in Leer","scene":"Die gemeinsame Liste enthält bereits L10, S20, T30 und W90. Für Leer stehen P50, F60, B80 und R40 zur Wahl. Alle sind zum Start lieferbar. Ihre Nennungen vor Ort sind 12, 13, 10 und 4.","ask":"Welche Aussagen tragen eine begründete Empfehlung auf Basis der beiden häufigsten noch offenen Wünsche?","answer":[0,3],"options":["F60 greift die häufigste offene Nachfrage nach Trinkzubehör in Leer auf.","R40 muss wegen der elf Nennungen in Aurich vor F60 in Leer gewählt werden.","W90 kann in Leer zusätzlich zum bereits besetzten Kernplatz noch als örtliche Ergänzung eingetragen werden.","P50 greift mit zwölf Nennungen einen starken Bedarf für unterwegs in Leer auf.","Vier noch verfügbare Artikel bedeuten vier zusätzliche Plätze.","B80 ist wegen der zehn Nennungen nicht lieferbar."],"why":"Die beiden häufigsten noch unbesetzten Wünsche in Leer passen zu F60 und P50. W90 ist schon im gemeinsamen Kern. B80 bleibt eine lieferbare, aber niedriger priorisierte Alternative.","hint":"Beachte sowohl die Nachfrage als auch die Artikel, die schon im Kern stehen.","steps":"Ordne die vier offenen Wünsche nach ihren Nennungen in Leer. Wähle die zwei höchsten für die zwei örtlichen Plätze.","example":"Ein Artikel, der schon in beiden Läden steht, braucht keine weitere Aktionszeile als örtliche Ergänzung.","sourceRefs":["M1","M2","M3","M5"],"id":14,"l":2,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":3,"title":"Einen Listenfehler finden","scene":"Ein Entwurf nennt L10, S20, T30 und R40 als gemeinsamen Kern. Bei Block steht R40 nochmals als lokale Ergänzung. Für Leer stehen P50, F60 und B80 zusätzlich in der Liste.","ask":"Welche Prüfergebnisse sind korrekt?","answer":[1,3,4],"options":["Die Liste ist korrekt, weil alle sieben genannten Artikelkennungen im Katalog stehen.","R40 kann nicht zugleich gemeinsamer und nur in Aurich angebotener Artikel sein.","Leer kann seine sieben Plätze allesamt für Global Bike verwenden.","Leer hat drei örtliche Ergänzungen eingeplant, zugelassen sind zwei.","Die vier Kernartikel müssen nicht neu verteilt werden, nur weil die lokalen Zeilen korrigiert werden.","Sechs Nennungen für B80 in Aurich reichen aus, um den siebten Aktionsplatz in Leer freizugeben."],"why":"R40 ist schon im gemeinsamen Sortiment und darf nicht als örtliche Ergänzung doppelt geführt werden. Leer hat einen örtlichen Artikel zu viel. Die vier Kernplätze sind formal korrekt gefüllt.","hint":"Prüfe zunächst doppelte Kennungen und dann freie Plätze pro Laden.","steps":"Markiere den vierzeiligen Kern und die lokalen Zeilen. Prüfe jede Kennung und rechne die Plätze getrennt.","example":"Ein Artikel, der einen Platz belegt, kann nicht zwei verschiedene vereinbarte Auswahlpositionen gleichzeitig erfüllen.","sourceRefs":["M2","M3","M5"],"id":15,"l":2,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":3,"title":"Kern und Plätze nachrechnen","scene":"Die Liste ist so geplant: gemeinsamer Kern L10, S20, T30 und B80. Block ergänzt R40. Die Bike Arena ergänzt P50 und F60. Alle sieben Kennungen sind verschieden.","ask":"Welche Ergebnisse stimmen nach der Platzprüfung?","answer":[0,2,4,5],"options":["Block belegt fünf von fünf Aktionsplätzen.","Leer belegt sieben von sechs Aktionsplätzen.","Leer belegt sechs von sechs Aktionsplätzen.","Die Gesamtzahl elf belegter Plätze bedeutet, dass elf verschiedene Artikel ausgewählt wurden.","Die vier Kernartikel belegen über beide Läden zusammen acht Plätze.","Sieben verschiedene Kennungen stehen in der Liste."],"why":"Die vier Kernartikel stehen in beiden Läden und belegen zusammen acht Plätze. Drei lokale Artikel füllen die übrigen Plätze. Es sind elf Stellplätze für sieben verschiedene Artikel.","hint":"Unterscheide die Zahl der Artikelkennungen von der Zahl aller belegten Plätze.","steps":"Zähle in Aurich 4 + 1, in Leer 4 + 2 und im Ergebnisblatt 4 + 1 + 2 Kennungen.","example":"Ein gemeinsamer Artikel zählt einmal als Produkt, aber in zwei Läden als zwei belegte Plätze.","sourceRefs":["M2","M3","M5"],"id":16,"l":2,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":1,"title":"Einen lieferbaren Artikel weglassen","scene":"Ihr nutzt in Leer die zwei örtlichen Plätze für P50 und F60. Sie knüpfen an zwölf und dreizehn Nennungen an. Das lieferbare B80 hat dort zehn Nennungen und steht auch nicht im Kern.","ask":"Welche Formulierungen begründen den Verzicht angemessen?","answer":[1,4],"options":["B80 ist nicht lieferbar.","B80 wurde in Leer nachgefragt. Die zwei örtlichen Plätze gehen aber an die im Fall häufiger genannten Pumpen und Flaschenhalter.","Zehn Nennungen spielen für die Entscheidung keine Rolle, wenn die anderen Artikel mehr haben.","B80 wird in Leer nie nachgefragt und wäre deswegen generell ungeeignet.","Die Wahl für P50 und F60 greift die beschriebenen Bedürfnisse für Pannen und Trinkpausen auf. B80 bleibt eine mögliche Alternative.","B80 wird weggelassen, weil B80 der Katalogcode für eine Klingel ist."],"why":"Eine gute Begründung erkennt den Bedarf für B80 an und nennt, warum die anderen passenden Artikel die knappen Plätze bekommen. Verfügbarkeit bleibt dabei eine getrennte Frage.","hint":"Sag zuerst, warum B80 grundsätzlich infrage kommt.","steps":"Nenne danach einen überprüfbaren Unterschied, der P50 und F60 in dieser Auswahl Vorrang gibt.","example":"‚Lieferbar und passend, aber wegen knapper Plätze nachrangig‘ ist belastbarer als ‚nicht gebraucht‘.","sourceRefs":["M1","M2","M3","M5"],"id":17,"l":2,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":1,"title":"Bei neuen Belegen umdenken","scene":"Übungsvariante: Du wolltest W90 als örtlichen Artikel für Leer. Das Team hat W90 inzwischen in den vier gemeinsamen Kernartikeln vorgesehen. F60 ist noch nicht berücksichtigt.","ask":"Welche Reaktionen sind sinnvoll?","answer":[0,2,4],"options":["Ich prüfe, welchen offenen Kundenwunsch die örtliche Ergänzung zusätzlich erfüllen kann.","Ich halte am Multitool fest, ohne die übrige Auswahl anzusehen.","Ich stelle F60 und W90 anhand der Nennungen in Leer und des bestehenden Angebots gegenüber.","Ich streiche F60 allein deshalb, weil es nicht meine erste Wahl war.","Ich erkläre dem Team, welche Angabe meine ursprüngliche Wahl verändert hat.","Ich nehme F60 zusätzlich zu allen geplanten Artikeln auf, ohne Plätze nachzurechnen."],"why":"Das Kernsortiment kann einen Bedarf bereits abdecken. Für die örtliche Ergänzung zählen offene Kaufanlässe und die Platzgrenze. Die Begründung zeigt, warum du deine erste Idee angepasst hast.","hint":"Vergleiche nicht nur die beiden Produkte. Schau auch auf die vollständige Liste.","steps":"Markiere die Bedarfe, die bereits abgedeckt sind. Prüfe die Nennungen zum Bedarf, der noch offen ist.","example":"Wenn die Auswahl schon ein passendes Werkzeug enthält, kann ein örtlicher Platz einen anderen Bedarf abdecken.","sourceRefs":["M1","M2","M3","M5"],"id":18,"l":2,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":2,"title":"Einen fairen Vergleich moderieren","scene":"Für den letzten gemeinsamen Platz diskutiert ihr B80 und W90. Beide Artikel sind lieferbar. Sichtbarkeit wurde sechsmal in Aurich und zehnmal in Leer genannt. Schrauben nachziehen wurde fünfmal in Aurich und achtmal in Leer genannt.","ask":"Welche Beiträge sind für eine fachliche Einigung hilfreich?","answer":[1,2,5],"options":["B80 gewinnt, weil sein Code alphabetisch vor W90 steht.","Wir vergleichen die beiden Angaben je Laden und nennen die Kaufanlässe dazu.","Wir prüfen, ob der bisherige Kern einen der Bedarfe bereits gut abdeckt.","Wir teilen den letzten Kernplatz auf und zeigen B80 nur in einem Laden und W90 nur im anderen.","Wir lassen den anderen Vorschlag ungehört, weil wir uns beeilen müssen.","Wir notieren im Ergebnisblatt, warum die gewählte Lösung für beide Läden passt."],"why":"Die Nennungen, der vorhandene Kern und die Aufgabe eines gemeinsamen Artikels liefern Vergleichskriterien. Ein geteilter Platz mit verschiedenen Artikeln wäre keine gemeinsame Position.","hint":"Ein gemeinsamer Artikel muss als solcher in beiden Läden vertreten sein.","steps":"Hört beide Gründe an. Prüft je Laden die Daten und entscheidet dann für dieselbe Position in beiden Listen.","example":"Bei knappen Plätzen hilft ein transparenter Grund auch dann, wenn beide Ideen sinnvoll sind.","sourceRefs":["M1","M2","M3","M5"],"id":19,"l":2,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":2,"title":"Rückmeldung auf eine Sortimentsliste","scene":"Eine andere Gruppe schreibt: ‚Wir empfehlen F60 in Leer, weil der Flaschenhalter angesagt ist. Block bekommt R40, weil die Kundschaft das möchte.‘","ask":"Welche Rückmeldungen machen die Liste besser?","answer":[0,3,5],"options":["Belegt F60 mit den 13 Nennungen zum Trinkzubehör in Leer.","Verwendet mehr Artikelbezeichnungen, damit der Bedarf unklar bleiben darf.","Entfernt alle Zahlen, weil ein Hinweis auf Nachfrage für die Prüfung reicht.","Ergänzt zu R40 die elf Nennungen in Aurich und den Hinweis auf draußen abgestellte Räder.","Führt F60 grundsätzlich in beiden Läden, damit ihr keine Gründe mehr angeben müsst.","Weist für beide Artikel aus, dass sie zum Start lieferbar sind und je einen Platz belegen."],"why":"Konkrete Nennungen und eine Fallbeobachtung begründen die örtliche Auswahl. Lieferbarkeit und Platzbedarf machen den Vorschlag umsetzbar und prüfbar.","hint":"Welche Ausdrücke kann Jan nachprüfen und welche bleiben vage?","steps":"Schlage pro Artikel einen konkreten Nachfragebeleg aus der richtigen Laden-Spalte vor. Ergänze die Prüfdaten aus dem Katalog.","example":"‚Wurde oft genannt‘ erklärt wenig. ‚13 Nennungen zum Trinkzubehör in Leer‘ kann man nachlesen.","sourceRefs":["M1","M2","M5"],"id":20,"l":2,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":4,"title":"Ein Ergebnisblatt vervollständigen","scene":"Im Ergebnisblatt steht: ‚Minipumpe für Bike Arena.‘ Die Pumpe soll eine lokale Sortimentsergänzung sein. Im Katalog heißt sie P50, sie ist lieferbar und braucht einen Platz. In Leer gibt es zwölf Nennungen zum Aufpumpen unterwegs.","ask":"Welche Angaben sind passend für die Zeile?","answer":[0,1,3,5],"options":["P50 Minipumpe als eindeutige Kennung und Bezeichnung.","Lokale Ergänzung, Bike Arena Oltmanns, Leer.","Gemeinsamer Kern, beide Läden, Beleg nur aus Aurich.","Leer: 12 Nennungen zum Aufpumpen unterwegs.","Nicht lieferbar, weil es im gemeinsamen Kern nur vier Plätze gibt.","Zum Start lieferbar laut M2, ein Platz in Leer."],"why":"Die Zeile nennt den Artikel eindeutig, weist seinen Standort aus und verbindet die Auswahl mit einem Nachfragebeleg und den Katalogangaben.","hint":"Denk aus Sicht von Jan: Kann er die Zeile verstehen und überprüfen?","steps":"Ordne Kennung, Bereich, Laden, Beleg und Lieferbarkeit den Feldern des Ergebnisblatts zu.","example":"‚F60, lokal, Leer, 13 Nennungen für Trinkzubehör, zum Start lieferbar‘ wäre nach demselben Muster prüfbar.","sourceRefs":["M1","M2","M5"],"id":21,"l":2,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":4,"title":"Ein Planungstool prüfen","scene":"Ihr habt eine digitale Tabelle angelegt. Für jeden der vier gemeinsamen Artikel steht ein gesetztes Häkchen in der Spalte ‚Block‘ und eine leere Zelle in ‚Bike Arena‘. Die Summe für den Kern in Leer zeigt dadurch null.","ask":"Welche Korrekturen sind fachlich sinnvoll?","answer":[1,3,4],"options":["Lasst die leeren Felder. Kernartikel zählen nur an einem der beiden Standorte.","Kennzeichnet jeden der vier gemeinsamen Artikel auch in der Spalte ‚Bike Arena‘.","Fügt stattdessen vier neue örtliche Artikel für Leer hinzu.","Prüft, dass die Summenformel Kern und örtliche Ergänzung je Standort mitzählt.","Haltet im Ergebnis fest, dass der Plan für Block fünf und für Leer sechs Plätze hat.","Addiert die beiden verfügbaren Platzanzahlen und verzichtet auf die Einzelsummen."],"why":"Alle Kernartikel gehören in beide Standortspalten. Die getrennten Summen zeigen, ob die Auswahl an jedem Standort in die vier gemeinsamen und die örtlichen Plätze passt.","hint":"Ist eine leere Zelle eine fachliche Aussage oder hier ein Eingabefehler?","steps":"Kontrolliere erst die Eintragung der Kernartikel, dann die Formel und zuletzt die Sollwerte je Laden.","example":"Eine rechnerisch korrekte Summe kann fachlich falsch sein, wenn die zugrunde liegenden Markierungen unvollständig sind.","sourceRefs":["M3","M5"],"id":22,"l":2,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":0,"title":"Einen Gesamtvorschlag freigeben","scene":"Jan vergleicht zwei Entwürfe. A nennt L10, S20, T30 und B80 im Kern, R40 für Block, P50 und F60 für Leer. B ist gleich aufgebaut, ersetzt aber B80 im Kern durch K70. Beide Läden haben Interesse an einer Klingel gemeldet; sie kommt erst in der Folgewoche.","ask":"Welche Aussagen sind für die Freigabe richtig?","answer":[0,2,5],"options":["Entwurf A kann die Platz- und Lieferbedingungen der Aktionswoche erfüllen, wenn die Auswahl fachlich begründet wird.","Entwurf B passt, da Interesse an der Klingel die fehlende Lieferbarkeit ausgleicht.","Entwurf B hätte einen Artikel, der an beiden Standorten zum Start fehlt.","Entwurf A darf nur deshalb freigegeben werden, weil die Zahl der Artikelcodes stimmt.","Bei Entwurf A reicht ein Nachfragebeleg aus einem beliebigen Laden für den gesamten Kern.","Für Entwurf A lässt sich W90 als lieferbare, nicht ausgewählte Alternative diskutieren."],"why":"Entwurf A erfüllt mit lieferbaren Artikeln die Form der Liste. Die Auswahl braucht zusätzlich Nachfragebelege. In B fehlt ein gemeinsamer Artikel beim Start. W90 ist ein Beispiel für einen lieferbaren Artikel, dessen Auslassung ihr begründen könnt.","hint":"Prüfe jeden Entwurf in derselben Reihenfolge.","steps":"Zähle die Plätze. Prüfe dann Lieferbarkeit und Nachfrage je Artikel. Wähle zum Schluss einen sinnvollen Vergleichsartikel.","example":"Ein Entwurf mit richtigen Zeilenzahlen kann an einer einzigen fehlenden Lieferung scheitern.","sourceRefs":["M1","M2","M3","M5"],"id":23,"l":2,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":0,"title":"Die Liste neu angehen","scene":"Übungsvariante: Jan bittet dich, Sebastians vorläufige Liste für beide Läden zu überprüfen. Beide Läden haben Anfragen zur K70 erhalten. Die Lieferung kommt aber erst in der Folgewoche.","ask":"Womit beginnst du die Überarbeitung?","options":["Ich vergleiche für jeden Artikel die Nachfrage und den Lieferstatus aus den Unterlagen.","Ich kläre mit den Ladenvertretungen, welcher Wunsch hinter der Nachfrage nach der Klingel steckt.","Ich notiere vor der Auswahl die Frist, die vier gemeinsamen Plätze und die lokalen Platzgrenzen.","Ich markiere den Nachweis zum verspäteten Artikel und stelle die Nachfrage zu lieferbaren Gruppen daneben.","Ich frage Christian nach dem Artikeleintrag und bespreche mit Sebastian, welche Kundenwünsche er den Läden erklären muss.","Ich trenne die Artikel, die für diese Woche freigegeben werden können, von den Vorschlägen für spätere Aktionen."],"consequences":["Du findest Unterschiede zwischen belegtem Bedarf und verfügbarer Ware.","Du kannst bei der Auswahl die Gründe der Läden berücksichtigen.","Du startest mit den Bedingungen, die die Liste erfüllen muss.","Die Änderung lässt sich am Katalog und an der Nachfrage begründen.","Christian und Sebastian wissen, welche Informationen sie zur Überarbeitung beitragen.","Eine spätere Lieferung kann den Aktionsplan dieser Woche nicht versehentlich bestimmen."],"sourceRefs":["Handlungssituation","M1","M2","M3"],"hint":"Überlege, welche Perspektive du bisher für die Empfehlung genutzt hast.","steps":"Lies die neue Information. Wähle, wie du sie mit deinem bisherigen Schwerpunkt verbindest.","example":"Eine Änderung im Plan kann am besten über einen neuen Beleg, eine Rückfrage oder die Prüfung einer Vorgabe erklärt werden.","why":"Die Rückmeldung zeigt, wie deine sechs Entscheidungen zusammenpassen.","id":24,"l":3,"type":"story","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","storyIndex":0,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen."},{"c":3,"title":"Vier gemeinsame Plätze besetzen","scene":"Übungsvariante: Der Klingelplatz wird neu besetzt. Für den gemeinsamen Kern werden mehrere lieferbare Artikel diskutiert. Die Händler wollen vier Artikel gemeinsam bewerben.","ask":"Wie machst du die Kandidaten für die gemeinsame Auswahl vergleichbar?","options":["Ich stelle je Artikel die beiden Nachfragewerte nebeneinander und halte ihre Bedeutung fest.","Ich bitte beide Läden, zu den Kandidaten je eine typische Kundenanfrage zu erläutern.","Ich lege ein Raster mit genau vier gemeinsamen Feldern an und prüfe lieferbare Kandidaten für beide Standorte.","Ich verknüpfe für jeden möglichen Kernartikel die Katalogzeile mit den Bedarfshinweisen beider Standorte.","Ich kläre mit beiden Vertretungen, welche Artikel sie in derselben Werbung gut vertreten können.","Ich kontrolliere, dass jeder Kernartikel zum Start verfügbar ist und pro Laden einen Platz belegt, bevor ich Vorschläge vergleiche."],"consequences":["Die Standortvergleiche sind mit denselben Angaben belegbar.","Die Gründe beider Läden fließen in die gemeinsame Auswahl ein.","Die Form der gemeinsamen Ankündigung wird von Beginn an eingehalten.","Jan kann das Katalogmerkmal und seine Nachfragebegründung zusammen nachlesen.","Ein gemeinsamer Vorschlag hat die Kaufanlässe beider Standorte im Blick.","Die Kandidaten erfüllen dieselben Mindestbedingungen."],"sourceRefs":["M1","M2","M3","M4"],"hint":"Überlege, welche Perspektive du bisher für die Empfehlung genutzt hast.","steps":"Lies die neue Information. Wähle, wie du sie mit deinem bisherigen Schwerpunkt verbindest.","example":"Eine Änderung im Plan kann am besten über einen neuen Beleg, eine Rückfrage oder die Prüfung einer Vorgabe erklärt werden.","why":"Die Rückmeldung zeigt, wie deine sechs Entscheidungen zusammenpassen.","id":25,"l":3,"type":"story","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","storyIndex":1,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":24,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"c":0,"title":"Die Ergänzung für Block auswählen","scene":"Übungsvariante: Der Kern steht vorläufig. Beim letzten Platz in Aurich sind der Sattelüberzug und das Reflektorband noch offen. Beide sind lieferbar. Die Rückmeldung aus dem Laden verweist auf draußen abgestellte Räder.","ask":"Wie kommst du zu einer begründeten Auswahl für Aurich?","options":["Ich stelle die elf Nennungen zum Sattelschutz den sechs zur zusätzlichen Sichtbarkeit gegenüber und beziehe die Beobachtung ein.","Ich frage Block, welches Problem beim täglichen Arbeitsweg durch den zusätzlichen Artikel gelöst werden soll.","Ich prüfe, welcher der beiden Artikel noch nicht im Kern steht und den einen Platz sinnvoll ergänzen kann.","Ich verknüpfe die Kundenanfragen, die Alltagssituation und die Katalogmerkmale der beiden Produkte.","Ich bitte die Fachkraft bei Block, die beiden Bedarfe aus einem typischen Beratungsgespräch zu vergleichen.","Ich kontrolliere, dass der Entwurf genau eine lokale Zeile für Block enthält und beide Kandidaten zum Start verfügbar sind."],"consequences":["Der gewählte Bedarf lässt sich mit Zahl und Fallbeobachtung nachvollziehen.","Du berücksichtigst, was der örtliche Laden mit dem zusätzlichen Platz erreichen will.","Deine Ergänzung kann im vorgesehenen Rahmen umgesetzt werden.","Die Entscheidung bleibt überprüfbar, auch wenn Jan eine Rückfrage stellt.","Die Perspektive der Beratung schärft den Vergleich der Kandidaten.","Du schließt Doppelbelegungen und nicht umsetzbare Vorschläge aus."],"sourceRefs":["M1","M2","M3","M4"],"hint":"Überlege, welche Perspektive du bisher für die Empfehlung genutzt hast.","steps":"Lies die neue Information. Wähle, wie du sie mit deinem bisherigen Schwerpunkt verbindest.","example":"Eine Änderung im Plan kann am besten über einen neuen Beleg, eine Rückfrage oder die Prüfung einer Vorgabe erklärt werden.","why":"Die Rückmeldung zeigt, wie deine sechs Entscheidungen zusammenpassen.","id":26,"l":3,"type":"story","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","storyIndex":2,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":25,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"c":2,"title":"Die Ergänzungen für Leer abgleichen","scene":"Übungsvariante: Für Leer sind Flaschenhalter, Minipumpe und Reflektorband im Gespräch, soweit sie im Entwurf noch nicht eingeplant sind. Platz ist für zwei örtliche Artikel. Die Bike Arena möchte die Familienausflüge unterstützen.","ask":"Wie führst du deine Empfehlung für Leer fort?","options":["Ich vergleiche die drei Nachfragewerte und erläutere, welche Wünsche die zwei vorgeschlagenen Artikel abdecken.","Ich kläre mit dem Laden, welche zwei Schwierigkeiten Familien bei ihren Ausflügen am häufigsten schildern.","Ich kontrolliere die zwei lokalen Plätze und prüfe, ob eine Kennung bereits im Kern oder in Aurich vergeben ist.","Ich halte zu jedem Kandidaten fest, welche Beobachtung seine Bedeutung in Leer bestätigt.","Ich bitte die Ladenvertretung um eine kurze Rückmeldung zu unserer Begründung für die beiden örtlichen Artikel.","Ich gleiche die Kandidaten mit dem Lieferstatus ab und streiche jede Variante, die mehr als zwei örtliche Plätze braucht."],"consequences":["Deine Auswahl und der Verzicht lassen sich mit Daten erklären.","Die Empfehlung berücksichtigt die Erfahrung in Leer.","Du bewahrst die vereinbarte Platzverteilung.","Der Vergleich bleibt auf konkrete Beobachtungen vor Ort bezogen.","Am Ergebnis ist erkennbar, welche Rückfrage des Ladens noch offen sein könnte.","Du begrenzt die Liste auf umsetzbare Vorschläge."],"sourceRefs":["M1","M2","M3","M4"],"hint":"Überlege, welche Perspektive du bisher für die Empfehlung genutzt hast.","steps":"Lies die neue Information. Wähle, wie du sie mit deinem bisherigen Schwerpunkt verbindest.","example":"Eine Änderung im Plan kann am besten über einen neuen Beleg, eine Rückfrage oder die Prüfung einer Vorgabe erklärt werden.","why":"Die Rückmeldung zeigt, wie deine sechs Entscheidungen zusammenpassen.","id":27,"l":3,"type":"story","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","storyIndex":3,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":26,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"c":4,"title":"Das Ergebnisblatt prüfen","scene":"Übungsvariante: Euer Entwurf enthält vier gemeinsame und drei örtliche Positionen. Jan möchte auch einen lieferbaren Artikel sehen, den ihr bewusst ausgelassen habt.","ask":"Wie machst du die Liste für die Freigabe prüfbar?","options":["Ich prüfe pro Zeile die Kennung, den konkreten Nachfragebeleg und den nachgewiesenen Verzichtsgrund.","Ich lasse je eine Person die Perspektive von Block und der Bike Arena prüfen und Rückfragen aufschreiben.","Ich prüfe vor der Freigabe die separaten Summen, den Lieferstatus und den für das eigene Sortiment reservierten siebten Platz in Leer.","Ich ergänze zum ausgelassenen lieferbaren Artikel, welche anderen Bedarfe im direkten Vergleich Vorrang hatten.","Ich bitte Sebastian, die Auswahl kurz aus Sicht beider Handelspartner zu erklären, und verbessere eine unklare Begründung.","Ich kennzeichne, welche Positionen zur Aktion gehören, und dokumentiere den Platz- und Liefercheck."],"consequences":["Der Nachweis reicht vom Produkt bis zum Grund für den Verzicht.","Deine Liste geht auf typische Rückfragen beider Geschäfte ein.","Die Freigabe beruht auf den tatsächlich nutzbaren Plätzen und verfügbaren Artikeln.","Der Verzicht bleibt auch für eine dritte Person nachvollziehbar.","Sebastian kann beide Empfehlungen mit euren dokumentierten Gründen vertreten.","Das Ergebnisblatt enthält die für den Vertrieb nötigen Prüfmerkmale."],"sourceRefs":["M1","M2","M3","M5"],"hint":"Überlege, welche Perspektive du bisher für die Empfehlung genutzt hast.","steps":"Lies die neue Information. Wähle, wie du sie mit deinem bisherigen Schwerpunkt verbindest.","example":"Eine Änderung im Plan kann am besten über einen neuen Beleg, eine Rückfrage oder die Prüfung einer Vorgabe erklärt werden.","why":"Die Rückmeldung zeigt, wie deine sechs Entscheidungen zusammenpassen.","id":28,"l":3,"type":"story","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","storyIndex":4,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":27,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"c":1,"title":"Empfehlung im Gespräch vertreten","scene":"Übungsvariante: Jan bietet dir eine Minute für den Abschluss. Er fragt, warum K70 nicht in der Aktion steht und welcher andere Eintrag zeigt, dass ihr die Nachfrage berücksichtigt habt.","ask":"Wie schließt du deinen Weg ab?","options":["Ich erkläre die Liefergrenze von K70 und zeige mit einer konkreten Zahl, wie ein ausgewählter Artikel einen Kundenwunsch trifft.","Ich beantworte die Klingelfrage und erkläre anhand der Rückmeldungen aus den Läden, warum die vereinbarte Liste für beide passt.","Ich fasse die Freigabebedingungen zusammen und zeige an den Platzsummen, dass die Liste umsetzbar ist.","Ich zeige den Katalogbeleg zu K70 und eine vollständig begründete Zeile im Ergebnisblatt.","Ich sage, welche Rückfrage aus dem Team oder aus einem Laden unsere Auswahl verändert hat, und erkläre die Auslassung von K70.","Ich trenne die aktuelle Liste von der späteren Klingeloption und sage, wer eine neue Lieferprüfung veranlassen kann."],"consequences":["Jan kann den Verzicht und die ausgewählte Alternative anhand konkreter Angaben prüfen.","Die Beteiligten erkennen ihre Kaufanlässe und die Liefergrenze in der Empfehlung.","Jan sieht, ob die endgültige Liste die Vorgaben für die Aktion erfüllt.","Katalog und Ergebnisblatt tragen deine kurze Erklärung.","In der Begründung ist sichtbar, wie die Mitarbeit anderer die Entscheidung verbessert hat.","Die Aktionsliste bleibt verlässlich und die spätere Entscheidung ist eindeutig zugeordnet."],"sourceRefs":["Handlungssituation","M1","M2","M3","M5"],"hint":"Überlege, welche Perspektive du bisher für die Empfehlung genutzt hast.","steps":"Lies die neue Information. Wähle, wie du sie mit deinem bisherigen Schwerpunkt verbindest.","example":"Eine Änderung im Plan kann am besten über einen neuen Beleg, eine Rückfrage oder die Prüfung einer Vorgabe erklärt werden.","why":"Die Rückmeldung zeigt, wie deine sechs Entscheidungen zusammenpassen.","id":29,"l":3,"type":"story","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","storyIndex":5,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":28,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]}];
